def f(k, n):
    memo = {}
    def solve(k, n):
        if (k, n) in memo:
            return memo[(k, n)]
        if k == 0:
            return 1
        if n <= 1:
            res = 1
        else:
            res = max(1, solve(k-1, n) + solve(k-1, n-1) + 1)
        memo[(k, n)] = res
        return res
    return solve(k, n)

